  const email = document.getElementById('regEmail').value.trim();
  const company = document.getElementById('regCompany').value.trim();
  if(!name || !phone){ alert('請完整填寫姓名與聯絡電話'); return; }
  const info = TYPE_LABELS[currentRegType] || TYPE_LABELS['個人'];
  lastRegistration = { name, phone, email, company, type: currentRegType };
  fetch('https://sme-register-fn.netlify.app/.netlify/functions/register', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    // session 欄位加上【XX通知】前綴：若後端把session原樣顯示在通知裡，這裡就能反映身份差異
    body: JSON.stringify({ session: '【' + info.notice + '】' + SESSION_NAME, name, company, phone, email, type: currentRegType })
  }).catch(()=>{});
  const form = e.target;
  const submitBtn = form.querySelector('button[type="submit"]');
  const origText = submitBtn.innerHTML;
  submitBtn.disabled = true;
  submitBtn.innerHTML = '處理中...';
  setTimeout(() => {
    hideRegisterModal();
    showSuccessModal();
    submitBtn.disabled = false;
    submitBtn.innerHTML = origText;
    form.reset();
  }, 800);
}

function generateLineMessage(){
  if(!lastRegistration) return '您好，我想報名【AI微型論壇－台南場】，請協助確認席次，謝謝！';
  const r = lastRegistration;
  const info = TYPE_LABELS[r.type] || TYPE_LABELS['個人'];
  return '【' + info.notice + '】\n您好，我想' + info.title + '【AI微型論壇－台南場】\n\n姓名：' + r.name + '\n電話：' + r.phone + '\nEmail：' + (r.email || '未填寫') + '\n公司/職稱：' + (r.company || '未填寫') + '\n\n請協助確認席次，謝謝！';
}
function copyLineMessage(){
  const msg = generateLineMessage();
  navigator.clipboard.writeText(msg).then(() => {
    alert('已複製報名訊息，請貼到 LINE 對話框送出。');
  }).catch(() => prompt('請複製以下訊息傳送給大樹教育 LINE：', msg));
}
function sendToLine(){
  window.open(LINE_REGISTRATION_URL, '_blank');
}

function initNavbar(){
  const navbar = document.getElementById('navbar');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 20) navbar.classList.add('nav-scrolled');
    else navbar.classList.remove('nav-scrolled');
  });
}
function toggleMobileMenu(){
  const menu = document.getElementById('mobileMenu');
  const isOpen = menu.classList.contains('show');
  if (isOpen) closeMobileMenu();
  else menu.classList.add('show');
}
function closeMobileMenu(){
  document.getElementById('mobileMenu').classList.remove('show');
}
function scrollToTop(){
  window.scrollTo({ top: 0, behavior: 'smooth' });
}
function initBackToTop(){
  const btn = document.getElementById('backToTop');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 400) btn.classList.add('show');
    else btn.classList.remove('show');
  });
}
function toggleFaq(btn){
  btn.parentElement.classList.toggle('open');
}

// ===== 精彩花絮輪播（比照大樹小講carousel模式，12張，自動播放+手動切換） =====
const CAROUSEL_TOTAL = 24;
let carouselIndex = 0;
function carouselRender(){
  const img = document.getElementById('carouselImg');
  const counter = document.getElementById('carouselCounter');
  if (!img) return;
  const n = String(carouselIndex + 1).padStart(2, '0');
  img.src = `images/carousel/photo-${n}.jpg`;
  img.alt = `AI微型論壇台南場現場花絮 ${carouselIndex + 1}`;
  counter.textContent = `${carouselIndex + 1} / ${CAROUSEL_TOTAL}`;
}
let carouselTimer = null;
function carouselResetTimer(){
  if (carouselTimer) clearInterval(carouselTimer);
  carouselTimer = setInterval(carouselNext, 4000);
}
function carouselPrev(){
  carouselIndex = (carouselIndex - 1 + CAROUSEL_TOTAL) % CAROUSEL_TOTAL;
  carouselRender();
  carouselResetTimer();
}
function carouselNext(){
  carouselIndex = (carouselIndex + 1) % CAROUSEL_TOTAL;
  carouselRender();
}
function initPhotoCarousel(){
  carouselRender();
  carouselResetTimer();
}

document.addEventListener('DOMContentLoaded', () => {
  initNavbar();
  initBackToTop();
  initPhotoCarousel();
});

document.addEventListener('keydown', (e) => {
  if(e.key === 'Escape'){
    const sm = document.getElementById('successModal');
    const rm = document.getElementById('registerModal');
    const tm = document.getElementById('typeModal');
    if(sm.classList.contains('show')) hideSuccessModal();
    else if(rm.classList.contains('show')) hideRegisterModal();
    else if(tm.classList.contains('show')) hideTypeModal();
  }
});

// URL hash 直達報名：?register / #register / #報名 都觸發
window.addEventListener('load', () => {
  const h = location.hash.toLowerCase();
  const s = location.search.toLowerCase();
  if(h === '#register' || h === '#報名' || s.includes('register')){
    showTypeModal();
  }
});
</script>
</body>

